        return $this->parse_ticker($response, $market);
    }

    public function parse_market_leverage_tiers($info, ?array $market = null): array {
        /**
         * @param {array} $info Exchange response for 1 $market
         * @param {array} $market CCXT $market
         */
        // array(
        //     array(
        //         "tier" => 1,
        //         "notionalCurrency" => "USD",
        //         "minNotional" => 10.0,
        //         "maxNotional" => 100.0,
        //         "maintenanceMarginRate" => 0.01,
        //         "maxLeverage" => 10
        //     ),
        //     {
        //         "tier" => 2,
        //         "notionalCurrency" => "USD",
        //         "minNotional" => 100.0,
        //         "maxNotional" => 1000.0,
        //         "maintenanceMarginRate" => 0.02,
        //         "maxLeverage" => 20
        //     }
        // )
        $results = array();
        for ($j = 0; $j < count($info); $j++) {
            $leverageTier = $info[$j];
            $results[] = array(
                'tier' => $this->safe_number($leverageTier, 'tier'),
                'symbol' => $market['symbol'],
                'currency' => $this->safe_string($leverageTier, 'notionalCurrency'),
                'minNotional' => $this->safe_number($leverageTier, 'minNotional'),
                'maxNotional' => $this->safe_number($leverageTier, 'maxNotional'),
                'maintenanceMarginRate' => $this->safe_number($leverageTier, 'maintenanceMarginRate'),
                'maxLeverage' => $this->safe_number($leverageTier, 'maxLeverage'),
                'info' => $leverageTier,
            );
        }
        return $results;
    }

